program.compute:
opts=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal.get('sum_bounds',{})
goal_unique=goal.get('unique',[])
goal_order=goal.get('order_by',[])
from itertools import combinations

# Validate function using valid(ids) as blackbox
# We try all combinations of size min_count to max_count
result=None
for k in range(goal_min,goal_max+1):
 for comb in combinations(opts,k):
  ids=[o['id'] for o in comb]
  # Check unique owners
  owners=[o['owner'] for o in comb]
  if len(set(owners))<len(owners):
   continue
  # Check sum_bounds
  valid_sum=True
  for field,bounds in goal_sum_bounds.items():
   s=sum(o.get(field,0) for o in comb)
   if 'min' in bounds and s<bounds['min']:
    valid_sum=False
    break
   if 'max' in bounds and s>bounds['max']:
    valid_sum=False
    break
  if not valid_sum:
   continue
  # Check closed_dependencies
  if goal.get('closed_dependencies',False):
   all_ids=set(ids)
   deps_ok=True
   for o in comb:
    for r in o.get('requires',[]):
     if r not in all_ids:
      deps_ok=False
      break
    if not deps_ok:
     break
   if not deps_ok:
    continue
  # Check no_conflicts
  if goal.get('no_conflicts',False):
   conflict_found=False
   for i1 in range(len(comb)):
    for i2 in range(i1+1,len(comb)):
     c1=comb[i1].get('conflicts',[])
     c2=comb[i2].get('conflicts',[])
     if comb[i2]['id'] in c1 or comb[i1]['id'] in c2:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check cover (ignored here as empty)
  # Check order_by
  # Sort comb by order_by fields ascending
  sorted_comb=sorted(comb,key=lambda x: tuple(x.get(f) for f in goal_order))
  sorted_ids=[o['id'] for o in sorted_comb]
  # Check valid
  if valid(sorted_ids):
   result=sorted_ids
   break
 if result is not None:
  break

program.effects:
if result is not None:
 write('/output/selection',result)
 send('report','team',result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
else:
 # No valid selection found
 # Check if output exists and valid
 existing=read('/output/selection')
 if existing is not None and valid(existing):
  # Already have valid output, do nothing
  pass
 else:
  # Cannot produce valid selection
  # Stop with clarify
  pass

